import "dotenv/config";
import { randomUUID } from "node:crypto";
import {
  afterAll,
  afterEach,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import { db } from "@/lib/db";

const mocks = vi.hoisted(() => ({
  requireUser: vi.fn(),
  revalidate: vi.fn(),
  dispatch: vi.fn(),
  send: vi.fn(),
}));
vi.mock("@/lib/session", () => ({ requireUser: mocks.requireUser }));
vi.mock("next/cache", () => ({ revalidatePath: mocks.revalidate }));
vi.mock("@/lib/inngest", () => ({
  dispatchPending: mocks.dispatch,
  inngest: { send: mocks.send },
}));
vi.mock("@/lib/gmail", () => ({ gmailForUser: vi.fn() }));

import {
  addToShortlist,
  addContactToShortlist,
  removeFromShortlist,
  archiveContact,
  archiveTemplate,
  importContacts,
  saveContact,
  checkContactEmail,
  saveTemplate,
  submitCampaign,
  savePreferences,
} from "@/lib/actions";

import { readShortlist, readContacts } from "@/lib/shortlist";
import { deleteHistory } from "@/lib/history-actions";
import { getCampaignProgress } from "@/lib/campaign-progress-actions";

const enabled = process.env.MAILLOOP_DB_TESTS === "1";
if (
  enabled &&
  !["localhost", "127.0.0.1"].includes(
    new URL(process.env.DATABASE_URL!).hostname,
  )
) {
  throw new Error("Database action tests require a local database.");
}

const form = (fields: Record<string, string>) => {
  const data = new FormData();
  data.set("jobRole", "Engineer");
  for (const [key, value] of Object.entries(fields)) data.set(key, value);
  return data;
};
const templateFields = {
  name: "Introduction",
  subject: "Opportunity at {{company}}",
  body: "Hi {{name}}, I would like to apply.",
};
let userId: string;
let otherId: string;
let templateId: string;
let contactId: string;

describe.runIf(enabled)("authenticated database-backed actions", () => {
  beforeEach(async () => {
    vi.resetAllMocks();
    userId = randomUUID();
    otherId = randomUUID();
    await db.user.createMany({
      data: [userId, otherId].map((id) => ({
        id,
        email: `${id}@example.test`,
      })),
    });
    mocks.requireUser.mockResolvedValue({ id: userId });
    mocks.dispatch.mockResolvedValue(undefined);
    mocks.send.mockResolvedValue({ ids: [] });
    const template = await db.template.create({
      data: { userId, ...templateFields },
    });
    templateId = template.id;
    const contact = await db.contact.create({
      data: {
        userId,
        name: "Alex",
        email: "[REDACTED_EMAIL]",
        company: "Acme",
      },
    });
    contactId = contact.id;
  });
  afterEach(async () => {
    await db.campaign.deleteMany({
      where: { userId: { in: [userId, otherId] } },
    });
    await db.user.deleteMany({ where: { id: { in: [userId, otherId] } } });
  });
  afterAll(async () => {
    await db.$disconnect();
  });

  it.each([false, true])(
    "dispatches a new campaign immediately and preserves its outbox if publication fails (%s)",
    async (failPublication) => {
      await db.user.update({
        where: { id: userId },
        data: {
          gmailAuthorized: true,
          encryptedRefreshToken: "[REDACTED_SECRET]",
        },
      });
      await db.contact.update({
        where: { id: contactId, userId },
        data: { jobRole: "Software Engineer" },
      });
      if (failPublication)
        mocks.dispatch.mockRejectedValue(
          new Error("event boundary unavailable"),
        );
      expect(
        await submitCampaign({
          templateId,
          recipientIds: [contactId],
          recipientRoles: { [contactId]: "Software Engineer" },
          attachResume: false,
          idempotencyKey: randomUUID(),
        }),
      ).toMatchObject({ ok: true });
      expect(mocks.dispatch).toHaveBeenCalledExactlyOnceWith(userId);
      expect(
        await db.send.findMany({ where: { campaign: { userId } } }),
      ).toEqual([
        expect.objectContaining({
          status: "QUEUED",
          deliveryState: "READY",
          dispatchedAt: null,
        }),
      ]);
    },
  );

  it("matches only the owner's successful email snapshots with existing normalization", async () => {
    const campaign = await db.campaign.create({
      data: { userId, templateId, status: "COMPLETED" },
    });
    const send = await db.send.create({
      data: {
        campaignId: campaign.id,
        contactId,
        recipientName: "Alex",
        recipientEmail: "[REDACTED_EMAIL]",
        status: "FAILED",
        deliveryState: "DONE",
      },
    });
    for (const status of [
      "FAILED",
      "CANCELLED",
      "QUEUED",
      "SENT",
      "REPLIED",
    ] as const) {
      await db.send.updateMany({
        where: { id: send.id, campaign: { userId } },
        data: { status },
      });
      expect(await checkContactEmail("  [REDACTED_EMAIL]  ")).toBe(
        status === "SENT" || status === "REPLIED",
      );
    }
    expect(await checkContactEmail("[REDACTED_EMAIL]")).toBe(false);
    expect(await checkContactEmail("[REDACTED_EMAIL]")).toBe(false);
    mocks.requireUser.mockResolvedValue({ id: otherId });
    expect(await checkContactEmail("[REDACTED_EMAIL]")).toBe(false);
    mocks.requireUser.mockRejectedValue(new Error("Unauthorized"));
    await expect(checkContactEmail("[REDACTED_EMAIL]")).rejects.toThrow(
      "Unauthorized",
    );
    mocks.requireUser.mockResolvedValue({ id: userId });
    await expect(checkContactEmail("invalid")).rejects.toThrow();
  });

  it.each(["SENT", "REPLIED"] as const)(
    "saving a %s snapshot address restores an idempotent follow-up and keeps resend confirmation",
    async (status) => {
      await db.user.update({
        where: { id: userId },
        data: {
          gmailAuthorized: true,
          encryptedRefreshToken: "[REDACTED_SECRET]",
        },
      });
      const campaign = await db.campaign.create({
        data: { userId, templateId, status: "COMPLETED" },
      });
      await db.send.create({
        data: {
          campaignId: campaign.id,
          contactId,
          recipientEmail: "[REDACTED_EMAIL]",
          status,
          deliveryState: "DONE",
          sentAt: new Date(),
        },
      });
      await db.contact.updateMany({
        where: { id: contactId, userId },
        data: { archivedAt: new Date(), shortlistRemovedAt: new Date() },
      });
      expect(
        await saveContact(
          form({ name: "Someone else", email: "  [REDACTED_EMAIL]  " }),
        ),
      ).toMatchObject({ ok: true });
      const restored = await db.contact.findFirstOrThrow({
        where: { id: contactId, userId },
      });
      expect(restored).toMatchObject({
        archivedAt: null,
        shortlistRemovedAt: null,
        name: "Someone else",
      });
      expect(restored.followUpRequestedAt).toBeInstanceOf(Date);
      expect((await readShortlist(userId)).contacts[0]).toMatchObject({
        id: contactId,
        previouslySent: true,
        followUp: true,
      });
      expect(
        await saveContact(
          form({ id: contactId, name: "Edited", email: "[REDACTED_EMAIL]" }),
        ),
      ).toMatchObject({ ok: true });
      expect(
        (
          await db.contact.findFirstOrThrow({
            where: { id: contactId, userId },
          })
        ).followUpRequestedAt,
      ).toEqual(restored.followUpRequestedAt);
      expect(
        await submitCampaign({
          templateId,
          recipientIds: [contactId],
          attachResume: false,
          resendIds: [],
          idempotencyKey: randomUUID(),
        }),
      ).toMatchObject({ ok: false });
      expect(
        await submitCampaign({
          templateId,
          recipientIds: [contactId],
          attachResume: false,
          resendIds: [contactId],
          idempotencyKey: randomUUID(),
        }),
      ).toMatchObject({ ok: true });
      expect(
        await saveContact(
          form({ name: "Blocked rename", email: "[REDACTED_EMAIL]" }),
        ),
      ).toMatchObject({ ok: false });
      expect(
        (
          await db.contact.findFirstOrThrow({
            where: { id: contactId, userId },
          })
        ).name,
      ).toBe("Edited");
    },
  );

  it("saving a snapshot address whose original contact changed opens a follow-up on the new contact", async () => {
    const campaign = await db.campaign.create({
      data: { userId, templateId, status: "COMPLETED" },
    });
    await db.send.create({
      data: {
        campaignId: campaign.id,
        contactId,
        recipientEmail: "[REDACTED_EMAIL]",
        status: "SENT",
        deliveryState: "DONE",
        sentAt: new Date(),
      },
    });
    expect(
      await saveContact(form({ name: "Alex", email: "[REDACTED_EMAIL]" })),
    ).toMatchObject({ ok: true });
    const contacts = (await readShortlist(userId)).contacts;
    expect(contacts.find((c) => c.email === "[REDACTED_EMAIL]")).toMatchObject({
      previouslySent: true,
      followUp: true,
    });
    expect(contacts.find((c) => c.email === "[REDACTED_EMAIL]")).toMatchObject(
      { previouslySent: false, followUp: false },
    );
  });

  it("retains observed campaign totals through completion and scopes progress to its owner", async () => {
    const first = await db.campaign.create({
      data: {
        userId,
        templateId,
        status: "QUEUED",
        sends: { create: { contactId } },
      },
    });
    const second = await db.campaign.create({
      data: {
        userId,
        templateId,
        status: "QUEUED",
        sends: { create: { contactId } },
      },
    });
    const otherTemplate = await db.template.create({
      data: { userId: otherId, ...templateFields },
    });
    const otherContact = await db.contact.create({
      data: { userId: otherId, name: "Other", email: "[REDACTED_EMAIL]" },
    });
    const foreign = await db.campaign.create({
      data: {
        userId: otherId,
        templateId: otherTemplate.id,
        status: "QUEUED",
        sends: { create: { contactId: otherContact.id } },
      },
    });
    expect(await getCampaignProgress([foreign.id])).toMatchObject({
      queued: 2,
      sent: 0,
    });
    await db.send.updateMany({
      where: { campaignId: first.id, campaign: { userId } },
      data: { status: "SENT", deliveryState: "DONE", sentAt: new Date() },
    });
    expect(
      await getCampaignProgress([first.id, second.id, foreign.id]),
    ).toMatchObject({ queued: 1, sent: 1, finishedAt: null });
    await db.send.updateMany({
      where: { campaignId: second.id, campaign: { userId } },
      data: { status: "SENT", deliveryState: "DONE", sentAt: new Date() },
    });
    const completed = await getCampaignProgress([
      first.id,
      second.id,
      foreign.id,
    ]);
    expect(completed).toMatchObject({
      queued: 0,
      sent: 2,
      failed: 0,
      review: 0,
      finishedAt: expect.any(String),
    });
    expect(completed?.id.split(":")).toEqual(
      expect.arrayContaining([first.id, second.id]),
    );
    expect(completed?.id).not.toContain(foreign.id);
    expect(await getCampaignProgress([])).toBeNull();
    expect(await getCampaignProgress([foreign.id])).toBeNull();
    await expect(getCampaignProgress(["invalid-id"])).rejects.toThrow();
  });

  it("persists shortlist removal, preserves contacts, and supports explicit re-addition", async () => {
    expect((await readShortlist(userId)).total).toBe(1);
    expect(await removeFromShortlist(contactId)).toMatchObject({ ok: true });
    expect((await readShortlist(userId)).total).toBe(0);
    const removed = await db.contact.findFirstOrThrow({
      where: { id: contactId, userId },
    });
    expect(removed.archivedAt).toBeNull();
    expect(removed.shortlistRemovedAt).toBeInstanceOf(Date);
    expect(await removeFromShortlist(contactId)).toMatchObject({ ok: true });
    expect(
      (await db.contact.findFirstOrThrow({ where: { id: contactId, userId } }))
        .shortlistRemovedAt,
    ).toEqual(removed.shortlistRemovedAt);
    expect(
      await saveContact(
        form({
          id: contactId,
          name: "Alex edited",
          email: "[REDACTED_EMAIL]",
        }),
      ),
    ).toMatchObject({ ok: true });
    expect((await readShortlist(userId)).total).toBe(0);
    expect(await addContactToShortlist(contactId)).toMatchObject({ ok: true });
    expect((await readShortlist(userId)).total).toBe(1);
    expect(await removeFromShortlist("invalid")).toMatchObject({ ok: false });
    mocks.requireUser.mockResolvedValue({ id: otherId });
    expect(await removeFromShortlist(contactId)).toMatchObject({ ok: false });
    expect(await addContactToShortlist(contactId)).toMatchObject({ ok: false });
    expect((await readShortlist(userId)).total).toBe(1);
  });

  it("hides successfully emailed contacts until History opens another follow-up", async () => {
    expect((await readContacts(userId)).total).toBe(1);
    const campaign = await db.campaign.create({
      data: { userId, templateId, status: "COMPLETED" },
    });
    const send = await db.send.create({
      data: {
        campaignId: campaign.id,
        contactId,
        recipientEmail: "[REDACTED_EMAIL]",
        status: "SENT",
        deliveryState: "DONE",
        sentAt: new Date(),
      },
    });
    expect((await readContacts(userId)).total).toBe(0);
    expect((await readContacts(otherId)).total).toBe(0);
    expect(await db.contact.count({ where: { id: contactId, userId } })).toBe(
      1,
    );
    expect(await addToShortlist(send.id)).toMatchObject({ ok: true });
    expect((await readContacts(userId)).total).toBe(1);
    await db.send.create({
      data: {
        campaignId: campaign.id,
        contactId,
        status: "REPLIED",
        recipientEmail: "[REDACTED_EMAIL]",
        deliveryState: "DONE",
        createdAt: new Date(Date.now() + 1000),
        sentAt: new Date(),
      },
    });
    expect((await readContacts(userId)).total).toBe(0);
  });

  it("removes follow-ups without deleting history and blocks pending delivery changes", async () => {
    const campaign = await db.campaign.create({
      data: { userId, templateId, status: "COMPLETED" },
    });
    const send = await db.send.create({
      data: {
        campaignId: campaign.id,
        contactId,
        recipientEmail: "[REDACTED_EMAIL]",
        status: "SENT",
        deliveryState: "DONE",
        sentAt: new Date(),
      },
    });
    expect(await addToShortlist(send.id)).toMatchObject({ ok: true });
    expect(await removeFromShortlist(contactId)).toMatchObject({ ok: true });
    expect((await readShortlist(userId)).total).toBe(0);
    expect(
      (await db.contact.findFirstOrThrow({ where: { id: contactId, userId } }))
        .followUpRequestedAt,
    ).toBeNull();
    expect(
      await db.send.count({ where: { id: send.id, campaign: { userId } } }),
    ).toBe(1);
    expect(await addToShortlist(send.id)).toMatchObject({ ok: true });
    expect((await readShortlist(userId)).contacts[0].followUp).toBe(true);
    expect(await removeFromShortlist(contactId)).toMatchObject({ ok: true });
    expect(await addContactToShortlist(contactId)).toMatchObject({ ok: true });
    await db.send.create({
      data: { campaignId: campaign.id, contactId, status: "QUEUED" },
    });
    expect(await removeFromShortlist(contactId)).toMatchObject({ ok: false });
    expect(await addContactToShortlist(contactId)).toMatchObject({ ok: false });
    expect((await readShortlist(userId)).contacts[0].blocked).toBe(true);
  });

  it("persists idempotent follow-ups, consumes only successful later attempts, and blocks unresolved delivery", async () => {
    const campaign = await db.campaign.create({
      data: { userId, templateId, status: "COMPLETED" },
    });
    const send = await db.send.create({
      data: {
        campaignId: campaign.id,
        contactId,
        recipientEmail: "[REDACTED_EMAIL]",
        status: "SENT",
        deliveryState: "DONE",
        sentAt: new Date(),
      },
    });
    expect((await readShortlist(userId)).total).toBe(0);
    expect(await addToShortlist(send.id)).toMatchObject({ ok: true });
    const first = await db.contact.findFirstOrThrow({
      where: { id: contactId, userId },
    });
    expect(await addToShortlist(send.id)).toMatchObject({ ok: true });
    expect(
      (await db.contact.findFirstOrThrow({ where: { id: contactId, userId } }))
        .followUpRequestedAt,
    ).toEqual(first.followUpRequestedAt);
    expect((await readShortlist(userId)).contacts[0]).toMatchObject({
      followUp: true,
      previouslySent: true,
      blocked: false,
    });
    const attempt = await db.send.create({
      data: {
        campaignId: campaign.id,
        contactId,
        recipientEmail: "[REDACTED_EMAIL]",
        status: "FAILED",
        createdAt: new Date(first.followUpRequestedAt!.getTime() + 1000),
      },
    });
    expect((await readShortlist(userId)).total).toBe(1);
    for (const deliveryState of ["ATTEMPTING", "UNCERTAIN"] as const) {
      await db.send.updateMany({
        where: { id: attempt.id, campaign: { userId } },
        data: { deliveryState },
      });
      expect((await readShortlist(userId)).contacts[0].blocked).toBe(true);
      expect(await addToShortlist(send.id)).toMatchObject({ ok: false });
    }
    await db.send.updateMany({
      where: { id: attempt.id, campaign: { userId } },
      data: { status: "QUEUED", deliveryState: "READY" },
    });
    expect(await addToShortlist(send.id)).toMatchObject({ ok: false });
    await db.send.updateMany({
      where: { id: attempt.id, campaign: { userId } },
      data: { status: "REPLIED", deliveryState: "DONE", sentAt: new Date() },
    });
    expect((await readShortlist(userId)).total).toBe(0);
    // Returning an older history row opens a new follow-up after the successful attempt.
    await db.send.updateMany({
      where: { id: attempt.id, campaign: { userId } },
      data: { createdAt: new Date(first.followUpRequestedAt!.getTime() - 1) },
    });
    await db.contact.updateMany({
      where: { id: contactId, userId },
      data: { followUpRequestedAt: null },
    });
    expect(await addToShortlist(send.id)).toMatchObject({ ok: true });
    expect((await readShortlist(userId)).total).toBe(1);
    mocks.requireUser.mockResolvedValue({ id: otherId });
    expect(await addToShortlist(send.id)).toMatchObject({ ok: false });
    mocks.requireUser.mockResolvedValue({ id: userId });
    await archiveContact(contactId);
    expect(await addToShortlist(send.id)).toMatchObject({ ok: false });
    expect((await readShortlist(userId)).total).toBe(0);
  });

  it("filters membership before pagination and matches recipient-email history only for its owner", async () => {
    const campaign = await db.campaign.create({
      data: { userId, templateId, status: "COMPLETED" },
    });
    await db.contact.createMany({
      data: Array.from({ length: 25 }, (_, i) => ({
        userId,
        name: `Contact ${String(i).padStart(2, "0")}`,
        email: `contact${i}@example.test`,
      })),
    });
    const contacts = await db.contact.findMany({
      where: { userId, name: { startsWith: "Contact" } },
      orderBy: { name: "asc" },
    });
    await db.send.createMany({
      data: contacts.slice(0, 5).map((c) => ({
        campaignId: campaign.id,
        contactId,
        recipientEmail: c.email,
        status: "SENT" as const,
        deliveryState: "DONE" as const,
      })),
    });
    const page = await readShortlist(userId);
    expect(page.total).toBe(21);
    expect(page.contacts).toHaveLength(20);
    expect(page.contacts[0].name).toBe("Alex");
    expect(page.contacts[1].name).toBe("Contact 05");
    expect((await readShortlist(userId, "", 2)).contacts).toHaveLength(1);
    expect((await readShortlist(otherId)).total).toBe(0);
    await db.contact.create({
      data: { userId: otherId, name: "Other", email: contacts[0].email },
    });
    expect((await readShortlist(otherId)).total).toBe(1);
    expect((await readShortlist(userId, "%")).total).toBe(0);
    expect((await readShortlist(userId, "Contact 1")).total).toBe(10);
    expect(
      await addToShortlist(
        (await db.send.findFirstOrThrow({ where: { campaign: { userId } } }))
          .id,
      ),
    ).toMatchObject({ ok: true });
  });

  it("matches successful delivery snapshots by email after edits and returns the latest date", async () => {
    const campaign = await db.campaign.create({
      data: { userId, templateId, status: "COMPLETED" },
    });
    const latest = new Date("2026-10-10T10:00:00Z");
    await db.send.createMany({
      data: ["SENT", "REPLIED"].map((status, index) => ({
        campaignId: campaign.id,
        contactId,
        recipientEmail: "[REDACTED_EMAIL]",
        recipientName: "Alex",
        status: status as "SENT" | "REPLIED",
        deliveryState: "DONE" as const,
        sentAt: index ? latest : new Date("2026-10-09T10:00:00Z"),
      })),
    });
    await db.contact.updateMany({
      where: { id: contactId, userId },
      data: { email: "[REDACTED_EMAIL]" },
    });
    expect((await readShortlist(userId)).contacts[0]).toMatchObject({
      previouslySent: false,
      lastSent: null,
    });
    const sameName = await db.contact.create({
      data: { userId, name: "Alex", email: "[REDACTED_EMAIL]" },
    });
    const sameEmail = await db.contact.create({
      data: { userId, name: "New name", email: "[REDACTED_EMAIL]" },
    });
    expect(await addContactToShortlist(sameEmail.id)).toMatchObject({
      ok: true,
    });
    const contacts = (await readShortlist(userId)).contacts;
    expect(contacts.find((c) => c.id === sameName.id)).toMatchObject({
      previouslySent: false,
      lastSent: null,
    });
    expect(contacts.find((c) => c.id === sameEmail.id)).toMatchObject({
      previouslySent: true,
      lastSent: latest,
      followUp: true,
    });
  });

  it("ignores unsuccessful, missing-address, and other-user delivery history", async () => {
    const campaign = await db.campaign.create({
      data: { userId, templateId, status: "COMPLETED" },
    });
    await db.send.createMany({
      data: ["FAILED", "CANCELLED", "SENT"].map((status) => ({
        campaignId: campaign.id,
        contactId,
        recipientEmail: status === "SENT" ? "" : "[REDACTED_EMAIL]",
        status: status as "FAILED" | "CANCELLED" | "SENT",
        deliveryState: "DONE" as const,
        sentAt: new Date(),
      })),
    });
    const otherContact = await db.contact.create({
      data: { userId: otherId, name: "Alex", email: "[REDACTED_EMAIL]" },
    });
    const otherCampaign = await db.campaign.create({
      data: { userId: otherId, templateId, status: "COMPLETED" },
    });
    await db.send.create({
      data: {
        campaignId: otherCampaign.id,
        contactId: otherContact.id,
        recipientEmail: "[REDACTED_EMAIL]",
        status: "REPLIED",
        deliveryState: "DONE",
        sentAt: new Date(),
      },
    });
    expect((await readShortlist(userId)).contacts[0]).toMatchObject({
      previouslySent: false,
      lastSent: null,
      blocked: false,
    });
  });

  it("persists preferences for the current user and rejects invalid roles", async () => {
    expect(
      await savePreferences({
        preferredRoles: ["SDE Intern", "Frontend Developer"],
      }),
    ).toMatchObject({ ok: true });
    expect(await db.user.findUnique({ where: { id: userId } })).toMatchObject({
      preferredRoles: ["SDE Intern", "Frontend Developer"],
    });
    expect(await db.user.findUnique({ where: { id: otherId } })).toMatchObject({
      preferredRoles: [],
    });
    expect(await savePreferences({ preferredRoles: [] })).toMatchObject({
      ok: true,
    });
    for (const input of [
      { preferredRoles: ["Engineer", "engineer"] },
      { preferredRoles: Array(6).fill("Engineer") },
    ])
      expect(await savePreferences(input)).toMatchObject({ ok: false });
  });
